import{_ as t,o,c as i,a2 as a}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Hotkeys","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/hotkeys.md","filePath":"user-guide/hotkeys.md","lastUpdated":1785993908000}'),n={name:"user-guide/hotkeys.md"};function r(s,e,d,l,h,c){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="hotkeys" tabindex="-1">Hotkeys <a class="header-anchor" href="#hotkeys" aria-label="Permalink to &quot;Hotkeys&quot;">​</a></h1><p>All global and in-app hotkeys below can be rebound from <strong>Settings → Hotkeys</strong>; defaults are shown here. See <a href="./settings/hotkeys-page.html">Settings → Hotkeys page</a> for the settings UI itself.</p><h2 id="global-hotkeys" tabindex="-1">Global hotkeys <a class="header-anchor" href="#global-hotkeys" aria-label="Permalink to &quot;Global hotkeys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>Toggle quick window</td><td>Double-tap <code>Ctrl</code></td><td>Can also be set to a full combo (e.g. <code>Alt+Space</code>) instead of a double-tap.</td></tr><tr><td>Quick switch</td><td><code>Ctrl+G</code></td><td>In a supported file dialog, navigates to the last folder captured from a supported file manager or the Quick Panel. An empty inline query also shows that destination as a result.</td></tr><tr><td>Select next item</td><td><code>Ctrl+N</code></td><td>Also works as the literal Down arrow. In the <a href="./settings/quick-panel.html">Quick Panel</a> it walks the whole tab rather than one group, carrying on into the next group at the end of the current one.</td></tr><tr><td>Select previous item</td><td><code>Ctrl+P</code></td><td>Also works as the literal Up arrow. Same whole-tab walk in the Quick Panel.</td></tr><tr><td>Jump to result 1–9</td><td><code>Ctrl</code> + digit</td><td>The modifier is configurable; the digit is always 1–9. The quick window shows each visible result&#39;s shortcut as a small badge next to it, so you don&#39;t have to count rows.</td></tr><tr><td>Open actions menu</td><td><code>Ctrl+O</code></td><td>Also works as the literal Right arrow on a selected result.</td></tr><tr><td>Complete from selection</td><td><code>Ctrl+Tab</code></td><td>In the quick window, fills the search box with the selected result&#39;s name/path.</td></tr><tr><td>QuickLook preview</td><td><code>Alt+P</code></td><td>Toggles the preview pane for the selected result. The <a href="./settings/quick-panel.html">Quick Panel</a> takes the same key, and docks the preview to whichever side of itself has room for it.</td></tr><tr><td>Previous keyword history</td><td><code>Alt+Up</code></td><td>Cycles backward through your recently typed queries.</td></tr><tr><td>Next keyword history</td><td><code>Alt+Down</code></td><td>Cycles forward through your recently typed queries.</td></tr><tr><td>Delete keyword history entry</td><td><code>Ctrl+Delete</code></td><td></td></tr><tr><td>Open full window</td><td><em>(none)</em></td><td>Opens the full window directly, carrying over the current query — same effect as left-clicking the <a href="#search-box-logo-icon">Quick Window&#39;s own logo</a> and choosing Show Main Window from the menu that opens, without that extra step. Not bound by default; set one from <strong>Settings → Hotkeys</strong>.</td></tr><tr><td>Keep window open</td><td><code>Ctrl+T</code></td><td>Stops the window hiding when focus moves elsewhere, so a query can be assembled out of text copied from other windows — hiding would otherwise clear the search box each time. Lasts for the current summon and ends with the next hide. In the quick window, middle-clicking the logo does the same thing and the logo brightens while it is on; pressing the summon hotkey while it is up but unfocused brings it back rather than hiding it. The <a href="./settings/quick-panel.html">Quick Panel</a> takes the same key, with a pin button of its own as the visible marker.</td></tr><tr><td>Toggle quick panel</td><td><code>Ctrl+F2</code></td><td>Opens the <a href="./settings/quick-panel.html">Quick Panel</a> docked into the bottom-right corner of whatever window is in front, or closes it if it is already up. Once it is open, holding the &quot;jump to result 1–9&quot; modifier and pressing 1–9 switches workspaces.</td></tr></tbody></table><h2 id="search-box-logo-icon" tabindex="-1">Search box logo icon <a class="header-anchor" href="#search-box-logo-icon" aria-label="Permalink to &quot;Search box logo icon&quot;">​</a></h2><p>The small logo icon in the search box (left or right side, depending on the window) does something different in each of the <a href="./getting-started.html#the-three-windows">three windows</a>:</p><ul><li><p><strong>Quick window</strong> — left-click (no movement) opens the same menu the tray icon&#39;s right-click shows (Show Main Window, Toggle Hotkeys, Settings, About, Clean Exit, Exit), anchored at the cursor; that menu&#39;s Show Main Window item also carries over whatever query you currently have typed. Click-and-drag moves the window, same as dragging any other part of the search bar — hold <strong>Ctrl</strong> while dragging (either the bar or the logo, and toggling Ctrl mid-drag works too) to constrain movement to vertical only, useful for nudging the window up or down without shifting it sideways. Right-click resets the window to its default on-screen position (not size) — the same one it centers to on first launch. A hover tooltip spells out all three behaviors.</p><p>The remembered position is relative to whichever monitor the window was last on, not an absolute screen coordinate — summon it again on a different monitor (or one with a different resolution or DPI scaling) and it reopens at the equivalent spot there instead of potentially landing off-screen or on the wrong display.</p></li><li><p><strong>Inline window</strong> — only clickable when the window is docked to a native Open/Save/Browse-for-folder dialog: left-click opens <a href="#quick-navigation-mouse">quick navigation</a>, same as the dedicated trigger below. Not clickable when docked to a plain Explorer window or the desktop, since there&#39;s nothing useful to navigate to in that case — no hover highlight or tooltip appears either, so it stays quiet rather than looking clickable and doing nothing.</p></li><li><p><strong>Main window</strong> — the logo is purely decorative there; clicking it does nothing.</p></li></ul><h2 id="quick-navigation-mouse" tabindex="-1">Quick navigation (mouse) <a class="header-anchor" href="#quick-navigation-mouse" aria-label="Permalink to &quot;Quick navigation (mouse)&quot;">​</a></h2><p>Enabled by default, toggled per-trigger in settings:</p><ul><li><strong>Double-click</strong> empty space on the desktop or inside an Explorer window to trigger quick navigation.</li><li><strong>Middle-click</strong> empty space on the desktop or inside an Explorer window — or the file list of a supported third-party file manager (Directory Opus, Total Commander, XYplorer, Files, ...), or a native Open/Save/Browse-for-folder dialog — to trigger quick navigation. Those other windows only respond to middle-click: double-clicking there already means &quot;open this,&quot; so double-click isn&#39;t repurposed. See <a href="./file-manager-support.html">Supported File Managers</a> for what each integration covers.</li><li>When the inline search window is docked to a native Open/Save/Browse-for-folder dialog, its own logo triggers quick navigation too — see <a href="#search-box-logo-icon">Search box logo icon</a> above.</li></ul><p>Any of these triggers pops a cascading menu of your Favorites, History, and configured quick-access folders (see <a href="./settings/favorites.html">Settings → Favorites</a> and <a href="./settings/history.html">Settings → History</a>) — plugins can contribute their own entries too, such as Total Commander&#39;s own Directory Hotlist if you&#39;ve set one up in <code>wincmd.ini</code>, Directory Opus&#39;s own Favorites menu, or a <a href="./instant-answers.html#custom-commands">Custom Command</a> flagged &quot;Show in Quick Navigation&quot; (optionally nested into a submenu by giving it a <code>/</code>-separated path). Each contributing plugin gets its own labeled section at the root of the menu, and the order those sections appear in is yours to set — see <a href="./settings/general.html#quick-navigation">Settings → General → Quick Navigation</a>. Clicking a folder navigates the target window there; clicking a file navigates there too, landing on the file selected in its containing folder rather than opening it — the one exception is the desktop, which has no existing window pane to navigate within, so there a folder or file is opened directly, same as double-clicking it would. Inside a file dialog specifically, clicking a file instead jumps the dialog to that file&#39;s folder — it deliberately never auto-confirms Open/Save on your behalf.</p><p>The <strong>Folder Cascader</strong> plugin is what actually builds this menu. Beyond Favorites and History (each independently toggleable), it has its own configurable list of quick-access folders — from <strong>Settings → Plugins → Folder Cascader → Configure</strong>, add a folder&#39;s path and an optional display name, and give it a <code>Submenu</code> value (e.g. <code>Tools/Network</code>, <code>/</code>-separated for multiple levels) to nest it under a category instead of showing it at the root. Every level of the menu — the root and any nested category — also has a small <strong>+</strong> button on its own header: click it to add the folder you&#39;re currently browsing right there, pre-filled with its name, path, and that level&#39;s own submenu path (all still editable before confirming), without leaving the menu to open Settings.</p><h2 id="hardcoded-keys-not-configurable" tabindex="-1">Hardcoded keys (not configurable) <a class="header-anchor" href="#hardcoded-keys-not-configurable" aria-label="Permalink to &quot;Hardcoded keys (not configurable)&quot;">​</a></h2><p>These always behave the same way regardless of your hotkey settings:</p><table tabindex="0"><thead><tr><th>Key</th><th>Context</th><th>Behavior</th></tr></thead><tbody><tr><td><code>Escape</code></td><td>Anywhere</td><td>Clears the search box if it has text; otherwise closes the window (or exits the actions menu).</td></tr><tr><td><code>Enter</code></td><td>Result list</td><td>Opens the selected result.</td></tr><tr><td><code>Ctrl+Enter</code></td><td>Result list</td><td>Locates the result in Explorer instead of opening it.</td></tr><tr><td><code>Ctrl+Shift+Enter</code></td><td>Result list</td><td>Opens the result elevated (Run as administrator).</td></tr><tr><td><code>Left</code> / <code>Right</code> arrow</td><td>Actions menu</td><td>Go back a menu level / enter a submenu.</td></tr><tr><td><code>Backspace</code></td><td>Actions menu</td><td>Exits the actions menu when the search box is already empty.</td></tr><tr><td><code>Alt+Space</code> / <code>Alt+F4</code></td><td>All of Lertaro&#39;s own windows</td><td><code>Alt+Space</code> is suppressed on all of them: none has a real title bar for the Windows system menu to belong to. <code>Alt+F4</code> closes the main and settings windows as usual; it stays suppressed on the quick, inline and QuickLook windows and the dialogs, which are shown and hidden rather than opened and closed.</td></tr></tbody></table><h2 id="plugin-action-hotkeys" tabindex="-1">Plugin action hotkeys <a class="header-anchor" href="#plugin-action-hotkeys" aria-label="Permalink to &quot;Plugin action hotkeys&quot;">​</a></h2><p>Plugins can register their own actions with a default hotkey (e.g. copy path (<code>Ctrl+Shift+C</code>), run as admin, or the built-in file actions — Cut <code>Ctrl+X</code>, Copy <code>Ctrl+C</code>, Paste <code>Ctrl+V</code>, Delete <code>Delete</code>, Permanently Delete <code>Shift+Delete</code>). These show up under <strong>Settings → Hotkeys → Plugin Actions</strong>, grouped by the plugin that registered them, and can be rebound the same way as built-in hotkeys.</p><h2 id="process-blacklist" tabindex="-1">Process blacklist <a class="header-anchor" href="#process-blacklist" aria-label="Permalink to &quot;Process blacklist&quot;">​</a></h2><p>If Lertaro&#39;s global hotkeys interfere with another application (a game capturing raw keyboard input, for example), add that process to the <strong>Process Blacklist</strong> — see <a href="./settings/hotkeys-page.html#process-blacklist">Settings → Hotkeys page</a>. While a blacklisted process is in the foreground, Lertaro&#39;s global hotkeys, keystroke interception, and the quick navigation mouse triggers above are all let through untouched.</p><p>Any foreground app that&#39;s genuinely full-screen gets this same treatment automatically — no blacklist entry needed. Either way, an active file dialog is always exempt, so quick navigation still works there.</p>',20)])])}const p=t(n,[["render",r]]);export{g as __pageData,p as default};
